#!/usr/bin/env python3
"""Embed our RS01 replacement sections, never the saved vendor image."""

import argparse
import hashlib
from pathlib import Path

from build_reset_speed_patch import (
    APP_OFFSET,
    OUTPUT_APP_SHA256,
    PAYLOAD_SIZE,
    ROOT,
    SECTIONS,
    compile_patch,
)


def render(llvm_bin=None):
    sections, _ = compile_patch(llvm_bin)
    lines = [
        "#pragma once",
        "// Generated by tools/embed_reset_speed_patch.py from our replacement sources.",
        "// Full application hash checks are mandatory at the caller.",
        '#include "child_lock_patch.h"',
        "namespace esphome::desk_firmware_update {",
        f'static constexpr const char *RS01_SHA = "{OUTPUT_APP_SHA256}";',
        f"static constexpr size_t RS01_PAYLOAD_SIZE = {PAYLOAD_SIZE};",
    ]
    for name, data in sections.items():
        lines += [
            f"// {name}: SHA-256 {hashlib.sha256(data).hexdigest()}",
            f"static constexpr uint8_t RS01_{name.upper()}[] = {{",
        ]
        for offset in range(0, len(data), 16):
            lines.append(
                "  " + ",".join(f"0x{b:02x}" for b in data[offset : offset + 16]) + ","
            )
        lines.append("};")
    lines += ["inline uint8_t rs01_byte(size_t offset, uint8_t stock) {"]
    for name in sections:
        offset = SECTIONS[name][0] - APP_OFFSET
        symbol = "RS01_" + name.upper()
        lines.append(
            f"  if (offset >= 0x{offset:x} && offset < 0x{offset:x} + sizeof({symbol})) return {symbol}[offset - 0x{offset:x}];"
        )
    lines += [
        "  return cl01_byte(offset,stock);",
        "}",
        "// The caller verifies exact CL01 input and RS01 output application hashes.",
        "inline bool apply_reset_speed(uint8_t *image, size_t size) {",
        "  const uint8_t vector[]={0xc1,0x73,0x00,0x08}, main[]={0xfd,0xf7,0xe6,0xf9};",
        "  const uint8_t parser[]={0xf0,0xb5,0x8c,0x46,0x01,0x79,0x04,0x68};",
        "  const uint8_t rx_init[]={0x00,0xf0,0xa9,0xfc};",
        "  const uint8_t complete[]={0xff,0xf7,0x60,0xfe};",
        "  const uint8_t speed[]={0x21,0x6a,0x60,0x68}, output[]={0x10,0xb5,0x07,0x4c,0x00,0x22,0x06,0x4b};",
        "  if (!image || size!=IMAGE_SIZE || std::memcmp(image+0x3c,vector,sizeof(vector)) ||",
        "      std::memcmp(image+0x5e88,main,sizeof(main)) || std::memcmp(image+0x1cf4,parser,sizeof(parser)) ||",
        "      std::memcmp(image+0x4e36,rx_init,sizeof(rx_init)) ||",
        "      std::memcmp(image+0x3bc8,speed,sizeof(speed)) ||",
        "      std::memcmp(image+0x340c,complete,sizeof(complete)) ||",
        "      std::memcmp(image+0x48d8,output,sizeof(output)) ||",
        "      std::memcmp(image+0x53ae,CL01_HOOK,sizeof(CL01_HOOK)) ||",
        "      std::memcmp(image+0x5df8,CL01_BOOT_HOOK,sizeof(CL01_BOOT_HOOK)) ||",
        "      std::memcmp(image+0x6400,CL01_CHILD_LOCK,sizeof(CL01_CHILD_LOCK))) return false;",
        "  for (size_t i=0x6c00; i<IMAGE_SIZE; ++i) if (image[i]!=255) return false;",
    ]
    for name in sections:
        offset = SECTIONS[name][0] - APP_OFFSET
        symbol = "RS01_" + name.upper()
        lines.append(f"  std::memcpy(image+0x{offset:x},{symbol},sizeof({symbol}));")
    lines += [
        "  return true;",
        "}",
        "}  // namespace esphome::desk_firmware_update",
        "",
    ]
    return "\n".join(lines)


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--llvm-bin", type=Path)
    p.add_argument("--check", action="store_true")
    a = p.parse_args()
    out = ROOT / "components/desk_firmware_update/reset_speed_patch.h"
    expected = render(a.llvm_bin)
    if a.check:
        if not out.is_file() or out.read_text() != expected:
            raise SystemExit(
                "reset_speed_patch.h is stale: run tools/embed_reset_speed_patch.py"
            )
    else:
        out.write_text(expected)


if __name__ == "__main__":
    main()
